  <title>Terms of Use Agreement</title>
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --bg:            #080d18;
      --surface:       #0f1623;
      --surface-2:     #161e2e;
      --border:        #2a3347;
      --border-hover:  #3d4f6b;
      --text-primary:  #e8edf5;
      --text-secondary:#8fa3bf;
      --accent:        #5b9cf6;
      --accent-hover:  #82b4f8;
      --error:         #f47171;
      --error-bg:      rgba(244, 113, 113, 0.08);
      --error-border:  rgba(244, 113, 113, 0.5);
      --success:       #4ade80;
      --success-bg:    rgba(74, 222, 128, 0.08);
      --btn-bg:        #2563eb;
      --btn-hover:     #1d4ed8;
      --btn-active:    #1e40af;
      --shadow:        0 4px 24px rgba(0, 0, 0, 0.4);
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
      background: var(--bg);
      color: var(--text-primary);
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      line-height: 1.6;
    }

    /* ── Skip link ─────────────────────────────────── */
    .skip-link {
      position: absolute;
      left: -9999px;
      top: auto;
      width: 1px;
      height: 1px;
      overflow: hidden;
    }
    .skip-link:focus {
      position: fixed;
      top: 1rem;
      left: 1rem;
      width: auto;
      height: auto;
      padding: 0.5rem 1rem;
      background: var(--surface);
      color: var(--accent);
      border: 2px solid var(--accent);
      border-radius: 6px;
      font-size: 0.9rem;
      font-weight: 500;
      text-decoration: none;
      z-index: 100;
    }

    /* ── Layout ────────────────────────────────────── */
    main {
      width: 100%;
      max-width: 460px;
    }

    .form-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 2.5rem 2rem;
      box-shadow: var(--shadow);
    }

    /* ── Heading ───────────────────────────────────── */
    h1 {
      font-size: 1.45rem;
      font-weight: 700;
      letter-spacing: -0.01em;
      color: var(--text-primary);
      margin-bottom: 0.4rem;
    }

    .form-description {
      font-size: 0.875rem;
      color: var(--text-secondary);
      margin-bottom: 2rem;
    }

    /* ── Form field wrapper ────────────────────────── */
    .form-field {
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1rem 1.125rem;
      margin-bottom: 1.25rem;
      transition: border-color 0.15s;
    }

    .form-field:hover {
      border-color: var(--border-hover);
    }

    .form-field.has-error {
      border-color: var(--error-border);
      background: var(--error-bg);
    }

    /* ── Checkbox row ──────────────────────────────── */
    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
    }

    input[type="checkbox"] {
      flex-shrink: 0;
      width: 18px;
      height: 18px;
      margin-top: 3px;
      accent-color: var(--accent);
      cursor: pointer;
    }

    input[type="checkbox"]:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 3px;
      border-radius: 3px;
    }

    .checkbox-label {
      font-size: 0.9375rem;
      cursor: pointer;
      color: var(--text-primary);
    }

    .required-star {
      color: var(--error);
      margin-left: 2px;
    }

    /* ── Help and error text ───────────────────────── */
    .help-text {
      font-size: 0.8125rem;
      color: var(--text-secondary);
      margin-top: 0.625rem;
      padding-left: calc(18px + 0.75rem);
    }

    .error-text {
      font-size: 0.8125rem;
      color: var(--error);
      margin-top: 0.5rem;
      padding-left: calc(18px + 0.75rem);
    }

    /* ── Links ─────────────────────────────────────── */
    .link {
      color: var(--accent);
      text-underline-offset: 2px;
    }
    .link:hover { color: var(--accent-hover); }
    .link:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 2px;
      border-radius: 2px;
    }

    /* ── Required note ─────────────────────────────── */
    .required-note {
      font-size: 0.8rem;
      color: var(--text-secondary);
      margin-bottom: 1.5rem;
    }

    /* ── Submit button ─────────────────────────────── */
    .submit-btn {
      display: block;
      width: 100%;
      padding: 0.75rem 1.5rem;
      background: var(--btn-bg);
      color: #fff;
      border: none;
      border-radius: 8px;
      font-size: 0.9375rem;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.15s;
      letter-spacing: 0.01em;
    }
    .submit-btn:hover  { background: var(--btn-hover); }
    .submit-btn:active { background: var(--btn-active); }
    .submit-btn:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 3px;
    }

    /* ── Success banner ────────────────────────────── */
    .success-banner {
      background: var(--success-bg);
      border: 1px solid rgba(74, 222, 128, 0.35);
      border-radius: 8px;
      padding: 1.125rem 1.25rem;
      text-align: center;
      color: var(--success);
      font-weight: 500;
      font-size: 0.9375rem;
      margin-top: 1rem;
    }

    /* ── Forced colors ─────────────────────────────── */
    @media (forced-colors: active) {
      .form-card,
      .form-field    { border: 1px solid ButtonText; }
      .submit-btn    { forced-color-adjust: auto; }
    }

    /* ── Narrow viewports (320 px reflow) ──────────── */
    @media (max-width: 380px) {
      .form-card { padding: 1.75rem 1.25rem; }
    }
  </style>
</head>
<body>

  <a href="#main" class="skip-link">Skip to main content</a>

  <main id="main">
    <div class="form-card">
      <h1>Create Account</h1>
      <p class="form-description">
        Review and accept the terms below to continue.
      </p>

      <form id="consent-form" novalidate>

        <div class="form-field" id="field-agree">
          <div class="checkbox-row">
            <input
              type="checkbox"
              id="agree-terms"
              name="agree-terms"
              required
              aria-describedby="agree-help agree-error"
            >
            <label for="agree-terms" class="checkbox-label">
              I agree to the
              <a href="#terms" class="link">Terms of Use</a><span
                class="required-star"
                aria-hidden="true"
              >*</span>
            </label>
          </div>

          <p id="agree-help" class="help-text">
            You must accept the Terms of Use before creating an account.
          </p>
          <p id="agree-error" class="error-text" hidden>
            Error: You must agree to the Terms of Use to continue.
          </p>
        </div>

        <p class="required-note">
          <span aria-hidden="true">* </span>Required field
        </p>

        <button type="submit" class="submit-btn">Agree and create account</button>
      </form>

      <div
        id="success-message"
        class="success-banner"
        hidden
        role="status"
      >
        ✓ Terms accepted — your account is ready.
      </div>
    </div>
  </main>

  <script>
    const form       = document.getElementById('consent-form');
    const checkbox   = document.getElementById('agree-terms');
    const errorText  = document.getElementById('agree-error');
    const fieldDiv   = document.getElementById('field-agree');
    const successMsg = document.getElementById('success-message');

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      clearError();

      if (!checkbox.checked) {
        showError();
        checkbox.focus();
        return;
      }

      form.hidden = true;
      successMsg.hidden = false;
    });

    checkbox.addEventListener('change', function () {
      if (checkbox.checked) clearError();
    });

    function showError() {
      checkbox.setAttribute('aria-invalid', 'true');
      errorText.hidden = false;
      fieldDiv.classList.add('has-error');
    }

    function clearError() {
      checkbox.removeAttribute('aria-invalid');
      errorText.hidden = true;
      fieldDiv.classList.remove('has-error');
    }
  </script>

</body>
</html>
